@@ -0,0 +1,81 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app, authHeaders } from "./helpers.js";
+
+test("missing or unknown API key returns 401", async () => {
+  const { handle } = app();
+  const missing = await handle({ path: "/items" });
+  assert.equal(missing.status, 401);
+  assert.equal(missing.body.error.code, "unauthorized");
+
+  const badFormat = await handle({ path: "/items", headers: { authorization: "Basic abc" } });
+  assert.equal(badFormat.status, 401);
+  assert.equal(badFormat.body.error.code, "unauthorized");
+
+  const unknown = await handle({ path: "/items", headers: { authorization: "Bearer nope" } });
+  assert.equal(unknown.status, 401);
+  assert.equal(unknown.body.error.code, "unauthorized");
+});
+
+test("viewer can read but cannot mutate or view audit", async () => {
+  const { handle } = app();
+  const headers = authHeaders("viewer");
+
+  assert.equal((await handle({ path: "/items", headers })).status, 200);
+  assert.equal((await handle({ path: "/reports/stock-value", headers })).status, 200);
+
+  const cookRes = await handle({ method: "POST", path: "/recipes/1/cook", headers, body: { portions: 1 } });
+  assert.equal(cookRes.status, 403);
+  assert.equal(cookRes.body.error.code, "forbidden");
+
+  const auditRes = await handle({ path: "/audit", headers });
+  assert.equal(auditRes.status, 403);
+  assert.equal(auditRes.body.error.code, "forbidden");
+});
+
+test("cook can cook, record waste, log temperatures and enter stock-take counts", async () => {
+  const { handle } = app();
+  const manager = authHeaders("manager");
+  const cook = authHeaders("cook");
+
+  assert.equal((await handle({ path: "/items", headers: cook })).status, 200);
+  assert.equal((await handle({ method: "POST", path: "/recipes/1/cook", headers: cook, body: { portions: 1 } })).status, 200);
+  assert.equal((await handle({ method: "POST", path: "/batches/1/waste", headers: cook, body: { qty: 0.5, reason: "spoiled" } })).status, 201);
+  assert.equal((await handle({ method: "POST", path: "/temperatures", headers: cook, body: { location: "fridge", celsius: 3 } })).status, 201);
+
+  const take = (await handle({ method: "POST", path: "/stocktakes", headers: manager, body: { location: "dry" } })).body;
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, headers: cook, body: { batchId: 6, counted: 12 } })).status, 200);
+
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/finish`, headers: cook })).status, 403);
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", headers: cook, body: { location: "fridge" } })).status, 403);
+  assert.equal((await handle({ method: "POST", path: "/orders", headers: cook, body: { supplierId: 1, lines: [] } })).status, 403);
+  assert.equal((await handle({ path: "/audit", headers: cook })).status, 403);
+});
+
+test("mutating requests write audit entries and GET /audit lists newest first", async () => {
+  const { handle } = app();
+  const manager = authHeaders("manager");
+  const cook = authHeaders("cook");
+
+  await handle({ path: "/items", headers: cook });
+  await handle({ method: "POST", path: "/temperatures", headers: cook, body: { location: "fridge", celsius: 4 } });
+  await handle({ method: "POST", path: "/stocktakes", headers: manager, body: { location: "dry" } });
+
+  const audit = await handle({ path: "/audit", headers: manager });
+  assert.equal(audit.status, 200);
+  assert.equal(audit.body.length, 2);
+  assert.deepEqual(audit.body[0], {
+    at: "2026-10-28T10:00:00.000Z",
+    keyName: "manager",
+    method: "POST",
+    path: "/stocktakes",
+    status: 201,
+  });
+  assert.deepEqual(audit.body[1], {
+    at: "2026-10-28T10:00:00.000Z",
+    keyName: "cook",
+    method: "POST",
+    path: "/temperatures",
+    status: 201,
+  });
+});
